import{_ as p,o as e,c as a,ai as o}from"./chunks/framework.scx6l_IK.js";const u=JSON.parse('{"title":"金刚经15分-布施要有智慧","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经15分-布施要有智慧.md","filePath":"60-原文段落/金刚经15分-布施要有智慧.md","lastUpdated":1778155802000}'),_={name:"60-原文段落/金刚经15分-布施要有智慧.md"};function r(s,t,n,c,d,i){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="金刚经15分-布施要有智慧" tabindex="-1">金刚经15分-布施要有智慧 <a class="header-anchor" href="#金刚经15分-布施要有智慧" aria-label="Permalink to &quot;金刚经15分-布施要有智慧&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/15了空居士讲《金刚经》-第十五分持经功德分20161209">15了空居士讲《金刚经》-第十五分持经功德分20161209</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>【答疑】</strong></p><p>**1.问：**前面说到等身布施，我觉得这个厉害啊，这种是一种很彻底的舍己为人了，为什么还是有我相呢？</p><p>**了空居士：**在《大佛顶如来密因修证了义诸菩萨万行首楞严经》，又叫《首楞严经》或者是《楞严经》，你们去打关键词：&quot;燃一指&quot;或者&quot;身燃一灯&quot;等等，如果你们看过《神仙传》，也有燃一臂，烧掉一个手臂的，很厉害，也有。《楞严经》里面说，燃一手指有多少功德，可能也有一些人读了《楞严经》之后也真的去燃一指。那么我们是不是也准备烧掉几个手指，或者烧掉一个手臂？佛祖告诉我们，虽然自古以来有这些做法，但是不用的。不要说烧一个手指两个手指，烧一个手臂两个手臂，烧一整个身体还不如受持《金刚经》而且为人演说，甚至听了，信心不逆，你还比不到。其实你着相地去怎么布施你还不开悟，就是死了百千万次，你还是着相啊还没开悟，当下能够升起信心，你就能够感受到刹那间开悟了，等一下你悟后迷了，但是你等一下又能开悟了。开悟的价值就是使你从凡夫位上升到菩萨位，你怎么去布施永远还是在凡夫位啊，是这样的啊。</p><p>**主持：**他能够以身布施，这个身包含着他的生命了，这实际上不是一种无我的行为吗？</p><p>**了空居士：**不一定，有时候或者是冲动吧。如果你是有大智慧，不是说什么时候都是以生命去布施啊，不一定的啊。</p><p>**主持：**或许他这里还有种去获取名的执着在那里。</p><p>**了空居士：**对对。我们打个比方，如果你看到一个坏人拿把刀在行凶，然后你不管三七二十一，冲上去让他一刀将我们砍死了，有没有功德？有的。但是很可惜，等一下凶手也要枪毙，我们也冤死。假如你很有智慧，观察一下，我要用什么办法来制服歹徒，或者我们先小心观察，能报警就报警，能够用其他更好的办法。譬如小时候来说吧，到处都有泥沙，一看到歹徒拿把刀，如果要制服他，至少要抓两把沙当面扔过去还是什么，可能像烟雾弹一样的搞一下，你很聪明地过去拿下他的刀还是什么，你就不能这么平白无故地冲上去，或者是拿一个凳子啊什么东西能够顶住他的刀的，你上去才行嘛，你不能凭着满腔的热血，冲上去被他一刀宰死了，等一下他也变成杀人犯，我们也很冤枉。所以说有时候不是说以身布施就是最完美的，不是的，还是要以智慧来面对，才是最完美的。</p><p>**主持：**听师父举的例子，就是说布施的时候是要有智慧地来布施。</p><p>**了空居士：**对对！该怎么做最完美我们就尽量那么做。</p><p>**主持：**我理解，即使在布施的时候他是以智慧来布施，但是他的目的上有不一样，比如说他是为了获取某种名或者利来布施的话，这是不是一种执着，这个跟目的还是有关系。</p><p>**了空居士：**有关系。</p><p>**主持：**这种布施可以称量的话，那是因为他的目的是着了功德相。</p><p>**了空居士：**对对。</p>',16)])])}const f=p(_,[["render",r]]);export{u as __pageData,f as default};
